import com.sun.fortress.numerics.DirectedRounding;
import java.util.*;

/* Writes the assertion lines of the two RR32 guards, each expected value
   computed as interpreter/glue/prim/RR32.java computes it. */
public class Gen {
    static final Map<String, Float> V = new LinkedHashMap<>();
    static final StringBuilder W = new StringBuilder(), C = new StringBuilder();
    static final StringBuilder WD = new StringBuilder(), CD = new StringBuilder();

    interface F1 { float f(float x); }
    interface F2 { float f(float x, float y); }
    interface B1 { boolean f(float x); }
    interface B2 { boolean f(float x, float y); }
    interface I1 { int f(float x); }
    interface L1 { long f(float x); }
    interface S1 { String f(float x); }

    /* a value written as a literal on both paths */
    static void lit(String name, String text) {
        float walk = (float) Double.parseDouble(text);   // narrow(asFloat(literal))
        float comp = Float.parseFloat(text);             // FFloatLiteral.asRR32
        if (Float.floatToRawIntBits(walk) != Float.floatToRawIntBits(comp))
            throw new Error("double rounding differs for " + text);
        V.put(name, walk);
        WD.append("  " + name + ": RR32 = narrow(" + text + ")\n");
        CD.append("  " + name + ": RR32 = " + text + "\n");
    }
    /* a negative value: walk narrows the negated literal, compiled negates by the helper */
    static void neglit(String name, String text) {
        float walk = (float) Double.parseDouble("-" + text);
        float comp = -Float.parseFloat(text);
        if (Float.floatToRawIntBits(walk) != Float.floatToRawIntBits(comp))
            throw new Error("double rounding differs for -" + text);
        V.put(name, walk);
        WD.append("  " + name + ": RR32 = narrow(-" + text + ")\n");
        CD.append("  " + name + ": RR32 = fNeg(" + text + ")\n");
    }
    static void derived(String name, float v, String walk, String comp) {
        V.put(name, v);
        WD.append("  " + name + ": RR32 = " + walk + "\n");
        CD.append("  " + name + ": RR32 = " + comp + "\n");
    }

    static float v(String n) { Float f = V.get(n); if (f == null) throw new Error("no value " + n); return f; }
    static String sub(String t, String x, String y) { return t.replace("$1", x).replace("$2", y == null ? "" : y); }
    static String q(String s) { return "\"" + s + "\""; }

    static String wf(String e, boolean simple) { return (simple ? e : "(" + e + ")") + ".asString"; }

    /* float result */
    static void ff(String wt, String ct, String label, float r, String x, String y, boolean comp) {
        String we = sub(wt, x, y);
        boolean simple = we.matches("[A-Za-z0-9]+");
        W.append("  assert(" + wf(we, simple) + ", " + q(Float.toString(r)) + ", " + q(label) + ")\n");
        if (comp) C.append("  assert(fToString(" + sub(ct, x, y) + ") = " + q(Float.toString(r)) + ", " + q(label) + ")\n");
    }
    static void u(String wt, String ct, String name, F1 f, String... xs) {
        for (String x : xs) ff(wt, ct, name + " of " + x, f.f(v(x)), x, null, true);
    }
    static void b(String wt, String ct, String name, F2 f, String... pairs) {
        for (String p : pairs) { String[] xy = p.split(" ");
            ff(wt, ct, name + " of " + xy[0] + " and " + xy[1], f.f(v(xy[0]), v(xy[1])), xy[0], xy[1], true); }
    }
    static void bool(String wt, String ct, String label, boolean r, String x, String y) {
        W.append("  assert(" + sub(wt, x, y) + ", " + r + ", " + q(label) + ")\n");
        C.append("  assert(" + (r ? "" : "NOT ") + sub(ct, x, y) + ", " + q(label) + ")\n");
    }
    static void ub(String wt, String ct, String name, B1 f, String... xs) {
        for (String x : xs) bool(wt, ct, name + " of " + x, f.f(v(x)), x, null);
    }
    static void bb(String wt, String ct, String name, B2 f, String... pairs) {
        for (String p : pairs) { String[] xy = p.split(" ");
            bool(wt, ct, name + " of " + xy[0] + " and " + xy[1], f.f(v(xy[0]), v(xy[1])), xy[0], xy[1]); }
    }
    static void ui(String wt, String ct, String name, I1 f, String... xs) {
        for (String x : xs) { int r = f.f(v(x)); String label = name + " of " + x;
            W.append("  assert(" + wf(sub(wt, x, null), false) + ", " + q(Integer.toString(r)) + ", " + q(label) + ")\n");
            C.append("  assert(" + sub(ct, x, null) + " = " + r + ", " + q(label) + ")\n"); }
    }
    static void ul(String wt, String ct, String name, L1 f, String... xs) {
        for (String x : xs) { long r = f.f(v(x)); String label = name + " of " + x;
            W.append("  assert(" + wf(sub(wt, x, null), false) + ", " + q(Long.toString(r)) + ", " + q(label) + ")\n");
            C.append("  assert(" + sub(ct, x, null) + " = " + r + ", " + q(label) + ")\n"); }
    }
    static void walkOnlyS(String wt, String name, S1 f, String... xs) {
        for (String x : xs) { String we = sub(wt, x, null);
            W.append("  assert(" + we + ", " + q(f.f(v(x))) + ", " + q(name + " of " + x) + ")\n"); }
    }
    static void gap() { W.append("\n"); C.append("\n"); }

    public static void main(String[] args) {
        lit("z", "0.0");
        derived("nz", -0.0f, "narrow(-0.0)", "fNeg(z)");
        lit("one", "1.0"); lit("two", "2.0"); lit("three", "3.0"); lit("half", "0.5");
        lit("a", "2.5"); neglit("b", "0.75"); lit("tenth", "0.1"); lit("sq", "6.25");
        lit("large", "300000000000000000000000000000000000000.0");
        lit("maxf", "340282346638528859811704183484516925440.0");
        lit("tiny", "0.0000000000000000000000000000000000000000000014");
        derived("inf", v("large") * v("large"), "large DOT large", "fMul(large, large)");
        derived("ninf", -v("inf"), "-inf", "fNeg(inf)");
        derived("nan", v("z") / v("z"), "z / z", "fDiv(z, z)");
        derived("nmaxf", -v("maxf"), "-maxf", "fNeg(maxf)");
        derived("ntiny", -v("tiny"), "-tiny", "fNeg(tiny)");
        lit("wide", "8589934592.0"); neglit("nwide", "6442450944.0");
        lit("seven", "10000000.0"); lit("milli", "0.001"); lit("small", "0.0001"); lit("mill", "1234567.0");
        lit("h35", "3.5"); neglit("nh25", "2.5"); lit("p27", "2.7"); neglit("np27", "2.7");
        if (!Float.isInfinite(v("inf")) || !Float.isNaN(v("nan")) || v("tiny") != Float.MIN_VALUE || v("maxf") != Float.MAX_VALUE)
            throw new Error("edge values");

        // asString and asExprString: floatToString
        u("$1", "$1", "asString", x -> x, "a", "b", "tenth", "z", "nz", "large", "maxf", "tiny", "ntiny", "inf", "ninf", "nan",
          "seven", "milli", "small", "mill");
        walkOnlyS("$1.asExprString", "asExprString", x -> Float.toString(x), "a", "b", "z", "nz", "maxf", "tiny", "inf", "ninf", "nan", "seven", "small");
        gap();
        ub("$1.isNaN", "fIsNaN($1)", "isNaN", x -> Float.isNaN(x), "nan", "a", "z", "nz", "inf", "ninf", "maxf", "tiny");
        ub("$1.isInfinite", "fIsInfinite($1)", "isInfinite", x -> Float.isInfinite(x), "inf", "ninf", "a", "z", "nz", "maxf", "tiny", "nan");
        ui("$1.rawBits", "fRawBits($1)", "rawBits", x -> Float.floatToRawIntBits(x), "a", "one", "b", "z", "nz", "maxf", "tiny", "ntiny", "inf", "ninf");
        gap();
        // nextUp at -0.0 and nextDown at 0.0 are left to their own test
        u("$1.nextUp", "fNextUp($1)", "nextUp", x -> DirectedRounding.nextUp(x), "one", "a", "b", "z", "tiny", "ntiny", "maxf", "nmaxf", "inf", "ninf", "nan");
        u("$1.nextDown", "fNextDown($1)", "nextDown", x -> DirectedRounding.nextDown(x), "one", "a", "b", "nz", "tiny", "ntiny", "maxf", "nmaxf", "inf", "ninf", "nan");
        u("|$1|", "fAbs($1)", "|x|", x -> Math.abs(x), "a", "b", "z", "nz", "large", "nmaxf", "tiny", "ntiny", "inf", "ninf", "nan");
        gap();
        // comparisons, none with NaN
        String[] cmp = {"a a", "a b", "b a", "z nz", "nz z", "tiny z", "z tiny", "ntiny nz", "large inf", "inf large", "maxf inf", "inf inf",
                        "ninf b", "ninf ninf", "ninf inf", "nmaxf ninf"};
        bb("$1 = $2", "fEQ($1, $2)", "=", (x, y) -> x == y, cmp);
        bb("$1 =/= $2", "fNE($1, $2)", "=/=", (x, y) -> x != y, cmp);
        bb("$1 < $2", "fLT($1, $2)", "<", (x, y) -> x < y, cmp);
        bb("$1 <= $2", "fLE($1, $2)", "<=", (x, y) -> x <= y, cmp);
        bb("$1 > $2", "fGT($1, $2)", ">", (x, y) -> x > y, cmp);
        bb("$1 >= $2", "fGE($1, $2)", ">=", (x, y) -> x >= y, cmp);
        gap();
        String[] mm = {"a b", "b a", "z nz", "nz z", "tiny z", "large inf", "ninf tiny", "maxf nmaxf", "a nan", "nan a"};
        b("$1 MIN $2", "fMin($1, $2)", "MIN", (x, y) -> Math.min(x, y), mm);
        b("$1 MAX $2", "fMax($1, $2)", "MAX", (x, y) -> Math.max(x, y), mm);
        gap();
        u("-$1", "fNeg($1)", "unary -", x -> -x, "a", "b", "z", "nz", "large", "maxf", "tiny", "inf", "ninf", "nan");
        b("$1 + $2", "fAdd($1, $2)", "+", (x, y) -> x + y, "a b", "one tenth", "z nz", "nz nz", "maxf maxf", "nmaxf nmaxf", "tiny tiny",
          "tiny ntiny", "inf one", "inf ninf", "nan one");
        b("$1 - $2", "fSub($1, $2)", "-", (x, y) -> x - y, "a b", "one tenth", "z z", "nz z", "tiny tiny", "nmaxf maxf", "ninf large",
          "inf inf", "nan one");
        String[] mul = {"a b", "tenth tenth", "nz a", "nz nz", "tiny tiny", "tiny two", "large large", "maxf half", "inf z", "ninf b", "nan one"};
        b("$1 DOT $2", "fMul($1, $2)", "DOT", (x, y) -> x * y, mul);
        b("$1 TIMES $2", "fMul($1, $2)", "TIMES", (x, y) -> x * y, mul);
        b("$1 $2", "fMul($1, $2)", "juxtaposition", (x, y) -> x * y, mul);
        b("$1 / $2", "fDiv($1, $2)", "/", (x, y) -> x / y, "a b", "one three", "one ninf", "large large", "nz a", "tiny two",
          "maxf tiny", "inf inf", "z z", "ninf b", "nan one");
        u("SQRT $1", "fSQRT($1)", "SQRT", x -> (float) Math.sqrt(x), "sq", "two", "z", "nz", "maxf", "tiny", "inf", "b", "ninf", "nan");
        gap();
        // directed roundings, each at an exact and an inexact operation and at the edges
        String[] add = {"a b", "one tenth", "tenth b", "z nz", "nz nz", "tiny tiny", "maxf maxf", "nmaxf nmaxf", "inf ninf", "nan one"};
        String[] sbt = {"a b", "one tenth", "b tenth", "z z", "nz z", "tiny ntiny", "maxf nmaxf", "nmaxf maxf", "inf inf", "nan one"};
        String[] mlt = {"a b", "tenth tenth", "tenth b", "tiny tiny", "ntiny tiny", "large large", "z inf", "nz inf", "nan one"};
        String[] dvd = {"a two", "one three", "b three", "tiny two", "ntiny two", "maxf tiny", "inf inf", "ninf inf", "nan one"};
        String[] srt = {"sq", "two", "z", "nz", "tiny", "maxf", "inf", "b", "nan"};
        b("$1 PLUS_UP $2", "fAddUpNoNaN($1, $2)", "PLUS_UP", DirectedRounding::addUpNoNaN, add);
